    localparam int CTR_PROC1_W = 7;
    logic [CTR_PROC1_W-1:0] ctr_proc1;
    localparam int N_REGS = 256;
    localparam int CTR_REGS_W = 8;
    logic [CTR_REGS_W-1:0] ctr_regs;
    localparam int N_TBL_DATA_MEMORY = 448;
    localparam int CTR_TBL_DATA_MEMORY_W = 9;
    logic [CTR_TBL_DATA_MEMORY_W-1:0] ctr_tbl_data_memory;

    // Live memory table: dmem
    localparam int TBL_DATA_MEMORY_ROWS = 32;
    localparam logic [12:0] TBL_DATA_MEMORY_ROW0 = 13'd1952;
    localparam logic [12:0] TBL_DATA_MEMORY_STRIDE = 13'd160;
    localparam logic [3:0] TBL_DATA_MEMORY_ADDCOL = 4'd0;
    localparam logic [3:0] TBL_DATA_MEMORY_DATACOL = 4'd6;
    localparam logic [12:0] TBL_DATA_MEMORY_MIDDLE = TBL_DATA_MEMORY_ROWS / 2;
    localparam logic [12:0] TBL_DATA_MEMORY_MAX_BASE = DMEM_DEPTH - 32;
    localparam logic [12:0] TBL_DATA_MEMORY_LAST_WORD = DMEM_DEPTH - 1;

    logic [5:0]  tbl_data_memory_row;          // the row of the table being drawn
    logic [3:0]  tbl_data_memory_col;          // the character of the row being drawn
    logic [31:0] tbl_data_memory_word;         // the word of the row, from the shadow
    logic [12:0] tbl_data_memory_base;         // the word address of the first row
    logic [12:0] tbl_data_memory_addr;         // the word address of the row drawn
    logic [12:0] tbl_data_memory_marked;       // the word address of the marked row
    logic [12:0] tbl_data_memory_access_base;  // the base of the last access
    logic [12:0] tbl_data_memory_access_word;  // the word address of the last access
    logic        tbl_data_memory_access_write; // the last access was a write
    logic        tbl_data_memory_marked_write; // the marked row is a write

    // The word the access touches, clamped to the memory.
    wire [12:0] tbl_data_memory_hit_word = (dm_addr > (TBL_DATA_MEMORY_LAST_WORD * 4))
                                   ? TBL_DATA_MEMORY_LAST_WORD : dm_addr[14:2];
    // The window base: the accessed word sits in the middle of the table.
    wire [12:0] tbl_data_memory_new_base = (tbl_data_memory_hit_word > TBL_DATA_MEMORY_MIDDLE)
                                    ? (tbl_data_memory_hit_word - TBL_DATA_MEMORY_MIDDLE) : 13'd0;
    wire [12:0] tbl_data_memory_clamped = (tbl_data_memory_new_base > TBL_DATA_MEMORY_MAX_BASE)
                                  ? TBL_DATA_MEMORY_MAX_BASE : tbl_data_memory_new_base;

    // No table reads the program memory yet: the shadow reads
    // word 0.
    assign imem_rd_addr = 32'h0;

    logic [GRP_W-1:0] grp_ctr;

    // Register table, stage 1: the row of the character being written.
    localparam logic [415:0] REG_ADDR = {13'd6886, 13'd6726, 13'd6566, 13'd6406, 13'd6246, 13'd6086, 13'd5926, 13'd5766, 13'd5606, 13'd5446, 13'd5286, 13'd5126, 13'd4966, 13'd4806, 13'd4646, 13'd4486, 13'd4326, 13'd4166, 13'd4006, 13'd3846, 13'd3686, 13'd3526, 13'd3366, 13'd3206, 13'd3046, 13'd2886, 13'd2726, 13'd2566, 13'd2406, 13'd2246, 13'd2086, 13'd1926};
