    wire mem_read_access  = mem_access && !mem_write_access;
    wire mem_access_live  = (instruction[6:0] == 7'b0000011) ||
                             (instruction[6:0] == 7'b0100011);
    wire mem_store_live   = (instruction[6:0] == 7'b0100011);

    // The table follows the last access.  The window and the marked row
    // are sampled at the sweep boundary, so every row of a sweep shows
